// Cloudflare Worker - serves HTML frontend + proxies Anthropic API
export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === '/api/chat' && request.method === 'POST') {
      const cors = {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
      };
      try {
        const { messages } = await request.json();
        const apiKey = env.ANTHROPIC_API_KEY;
        if (!apiKey) return new Response(JSON.stringify({ error: 'API key not set.' }), { status: 500, headers: { 'Content-Type': 'application/json', ...cors } });
        const resp = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'anthropic-version': '2023-06-01', 'x-api-key': apiKey },
          body: JSON.stringify({ model: 'claude-sonnet-4-20250514', max_tokens: 1000,
            system: 'You are StartupBridge AI Advisor - expert startup mentor for the Indian market. Give practical, specific, actionable advice using Indian context: INR currency, Indian regulations (SEBI, RBI, FSSAI, MCI), Indian consumer behavior. Mention FREE and PAID tools. Be direct and specific.',
            messages }),
        });
        const data = await resp.json();
        if (!resp.ok) return new Response(JSON.stringify({ error: data.error?.message || 'API error' }), { status: resp.status, headers: { 'Content-Type': 'application/json', ...cors } });
        return new Response(JSON.stringify({ text: data.content?.[0]?.text || 'No response.' }), { status: 200, headers: { 'Content-Type': 'application/json', ...cors } });
      } catch(e) {
        return new Response(JSON.stringify({ error: e.message }), { status: 500, headers: { 'Content-Type': 'application/json' } });
      }
    }

    if (request.method === 'OPTIONS') return new Response(null, { headers: { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'POST, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type' } });

    const b64 = "";
    const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
    const html = new TextDecoder().decode(bytes);
    return new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
  },
};
